// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DAO c;

    function setUp() public {
        c = new DAO();
    }

    function _run(uint256 oldProposalID, uint256 newProposalID) internal {
        vm.assume(oldProposalID != newProposalID);
        bool reverted;
        try c.cancelProposal(oldProposalID, newProposalID) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted);
    }

    function testFuzz_run(uint256 oldProposalID, uint256 newProposalID) public {
        _run(oldProposalID, newProposalID);
    }

    receive() external payable {}
}
